const input = $input.first().json.body || $input.first().json;
const invoices = Array.isArray(input.invoices) ? input.invoices : [];
const now = input.asOfDate ? new Date(input.asOfDate) : new Date();
const rows = invoices.map((x, i) => {
  const due = x.dueDate ? new Date(x.dueDate) : null;
  const amount = Number(x.totalAmount || 0);
  const paid = String(x.status || '').toLowerCase() === 'paid';
  return { ref: x.invoiceNumber || `invoice-${i + 1}`, amount, status: paid ? 'paid' : (due && due < now ? 'overdue' : 'open'), dueDate: x.dueDate || null, daysOverdue: !paid && due && due < now ? Math.floor((now - due) / 86400000) : 0 };
});
const summary = { asOfDate: now.toISOString().slice(0, 10), count: rows.length, paidCount: rows.filter(x => x.status === 'paid').length, openCount: rows.filter(x => x.status === 'open').length, overdueCount: rows.filter(x => x.status === 'overdue').length, openBalance: rows.filter(x => x.status !== 'paid').reduce((s, x) => s + x.amount, 0), records: rows };
const prompt = `Review this anonymized maintenance-dues summary for a finance administrator. Identify data-quality issues, useful aggregate patterns, and neutral follow-up priorities. Do not decide penalties, waive dues, contact residents, or post payments. Do not infer ability or willingness to pay. Return concise JSON with keys observations (array), dataQualityFlags (array), suggestedHumanChecks (array).
${JSON.stringify(summary)}`;
return [{ json: { summary, prompt } }];

const response = $input.first().json;
const summary = $('Calculate Dues Summary').first().json.summary;
let review;
try { review = JSON.parse(response.candidates[0].content.parts[0].text); } catch { review = { observations: [], dataQualityFlags: ['AI response could not be parsed; review source data manually.'], suggestedHumanChecks: [] }; }
return [{ json: { status: 'review_ready', summary, aiReview: review, requiresHumanApproval: true, actionsTaken: [] } }];
